// Bug: data race
var count = 0
DispatchQueue.concurrentPerform(iterations: 1000) { _ in count += 1 }  // often < 1000

// Fix with an actor
actor Counter {
    private(set) var value = 0
    func increment() { value += 1 }
}

// Classic deadlock
DispatchQueue.main.async {
    DispatchQueue.main.sync { }   // main waits for main: frozen forever
}
